create or replace function public.get_documentation_payment_checkout(_payment_id uuid) returns jsonb language plpgsql security definer set search_path=public as $$ declare p public.estate_documentation_payments; dt public.documentation_types; o public.orders; begin select * into p from public.estate_documentation_payments where id=_payment_id and user_id=auth.uid() for update; if not found then raise exception 'Documentation payment not found'; end if; select * into dt from public.documentation_types where id=p.documentation_type_id; if not found or coalesce(dt.price,0)<=0 then raise exception 'Documentation price is not configured'; end if; if p.status not in ('pending','approved') then raise exception 'Documentation payment is not payable in its current status'; end if; if p.amount is distinct from dt.price then update public.estate_documentation_payments set amount=dt.price,updated_at=now() where id=p.id; p.amount:=dt.price; end if; select * into o from public.orders where id=p.order_id and user_id=auth.uid(); return jsonb_build_object('payment_id',p.id,'order_id',p.order_id,'amount',p.amount,'currency','NGN','reference',p.reference,'documentation_type_id',dt.id,'documentation_name',dt.name,'property_name',coalesce((o.items->0->>'property_name'),'')); end; $$; revoke all on function public.get_documentation_payment_checkout(uuid) from public; grant execute on function public.get_documentation_payment_checkout(uuid) to authenticated;
